<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= htmlspecialchars($def['title']) ?> - BloodLink</title><link rel="stylesheet" href="public/assets/css/style.css"></head><body><header class="topbar"><a class="brand" href="index.php">BloodLink<small>Services de santé</small></a><a class="btn secondary" href="index.php">Retour</a></header><main class="container"><p class="eyebrow">CONSULTATION</p><h1><?= htmlspecialchars($def['title']) ?></h1><section class="cards"><?php foreach($rows as $row): ?><article class="card"><h2><?= htmlspecialchars($row['nom']??$row['etablissement']??'Avis') ?></h2><?php foreach($def['fields'] as $key=>$label): if(!isset($row[$key])||$key==='nom') continue; ?><p><b><?= htmlspecialchars($label) ?> :</b> <?= htmlspecialchars((string)$row[$key]) ?></p><?php endforeach; ?></article><?php endforeach; ?><?php if(!$rows): ?><p>Aucune information publiée pour le moment.</p><?php endif; ?></section></main></body></html>
